def trigger_emotional_intervention(
    user_id,
    real_time_metrics,
    historical_data
):
    """
    Return a supportive learning intervention.

    Inputs:
      user_id: anonymized student identifier
      real_time_metrics: {
          "typing_speed": float | None,
          "voice_pitch": float | None,
          "sentiment_score": float | None,   # model output; not a diagnosis
          "explicit_check_in": str | None,   # e.g. "frustrated", "fine", "tired"
          "task_error_rate": float | None,
          "time_on_task": int | None
      }
      historical_data: {
          "support_opt_in": bool,
          "preferred_interventions": list,
          "baseline_metrics": dict,
          "recent_interventions": list,
          "accessibility_preferences": dict,
          "safety_preferences": dict
      }
    """

    # 1. Respect consent, privacy, and cooldown settings.
    if not historical_data.get("support_opt_in", False):
        return {
            "type": "none",
            "message": None,
            "reason": "emotional_support_not_enabled"
        }

    if intervention_in_cooldown(
        user_id,
        historical_data.get("recent_interventions", [])
    ):
        return {
            "type": "none",
            "message": None,
            "reason": "cooldown_active"
        }

    # Do not retain raw voice, typing, or sentiment data unnecessarily.
    metrics = minimize_and_validate(real_time_metrics)

    # 2. Give explicit student statements priority over inferred signals.
    stated_state = metrics.get("explicit_check_in")

    if stated_state in ["distressed", "unsafe", "in crisis"]:
        return route_to_human_or_emergency_support(
            user_id=user_id,
            safety_preferences=historical_data.get("safety_preferences", {}),
            message=(
                "I'm sorry you're going through this. "
                "Would you like to pause learning and connect with a trusted "
                "person or local support service?"
            )
        )

    # 3. Compare weak signals with the student's own baseline.
    baseline = historical_data.get("baseline_metrics", {})
    signals = []

    if is_meaningfully_lower(
        metrics.get("typing_speed"),
        baseline.get("typing_speed")
    ):
        signals.append("slower_typing")

    if is_meaningfully_different(
        metrics.get("voice_pitch"),
        baseline.get("voice_pitch")
    ):
        signals.append("voice_change")

    if below_threshold(metrics.get("sentiment_score"), -0.5):
        signals.append("negative_language")

    if above_threshold(metrics.get("task_error_rate"), 0.45):
        signals.append("repeated_errors")

    # Voice pitch and sentiment alone should never trigger a high-stakes action.
    confidence = estimate_support_signal_confidence(
        signals=signals,
        explicit_state=stated_state,
        task_error_rate=metrics.get("task_error_rate")
    )

    if confidence < 0.5:
        return {
            "type": "none",
            "message": None,
            "reason": "insufficient_evidence"
        }

    # 4. Use a brief, transparent check-in rather than assuming emotion.
    if stated_state is None:
        return {
            "type": "check_in",
            "message": (
                "You seem to be having a harder time than usual. "
                "Would you like to continue, review an example, take a short "
                "break, or adjust the difficulty?"
            ),
            "choices": [
                "continue",
                "review_example",
                "take_break",
                "adjust_difficulty"
            ],
            "reason": "possible_learning_friction"
        }

    # 5. Select a low-pressure educational intervention.
    preferred = historical_data.get("preferred_interventions", [])

    if stated_state in ["frustrated", "confused"] or "repeated_errors" in signals:
        intervention = {
            "type": "scaffold",
            "message": (
                "Let's reduce the difficulty for one step. "
                "Here's a worked example, then you can try a similar problem."
            ),
            "actions": [
                "show_worked_example",
                "offer_optional_hint",
                "retry_with_similar_problem"
            ]
        }

    elif stated_state in ["tired", "overwhelmed"] or "slower_typing" in signals:
        intervention = {
            "type": "break_or_pacing",
            "message": (
                "You can take a short break or switch to a lighter review task. "
                "Your progress will be saved."
            ),
            "actions": [
                "pause_for_5_minutes",
                "switch_to_low_stakes_review",
                "continue_current_task"
            ]
        }

    elif stated_state in ["discouraged"] or "negative_language" in signals:
        intervention = {
            "type": "encouragement_and_reflection",
            "message": (
                "This topic is challenging, but the recent errors show us "
                "exactly what to practice. Would you like a hint or a simpler "
                "example first?"
            ),
            "actions": [
                "show_hint",
                "simplify_example",
                "review_mistake"
            ]
        }

    else:
        intervention = {
            "type": "choice",
            "message": (
                "How would you like to proceed?"
            ),
            "actions": [
                "continue",
                "get_hint",
                "review_concept",
                "take_break"
            ]
        }

    # 6. Apply user preferences without overriding current choice.
    intervention = apply_preferences(
        intervention,
        preferred,
        accessibility_preferences=historical_data.get(
            "accessibility_preferences", {}
        )
    )

    # 7. Log only the minimum event needed for evaluation.
    record_support_event(
        user_id=user_id,
        intervention_type=intervention["type"],
        signals_used=signals,          # not raw voice or raw text
        student_choice_required=True
    )

    return intervention
