def select_peer_for_motivation(
    current_user_id,
    user_emotional_state,
    peer_database,
    user_profile,
    strategy="auto"
):
    """
    Select an anonymized peer-learning example.

    Strategies:
      - "aspiration": show a credible next-step example
      - "relatability": show a learner with similar challenges and progress
      - "auto": choose based on explicit learner preference and learning context

    user_emotional_state is optional and coarse-grained. It must not be used
    to exploit distress, shame, or emotional vulnerability.
    """

    # 1. Require consent and protect privacy.
    if not user_profile.get("peer_comparison_opt_in", False):
        return {
            "type": "none",
            "reason": "peer_comparison_disabled"
        }

    if user_profile.get("comparison_sensitivity") == "avoid":
        return {
            "type": "none",
            "reason": "comparison_not_preferred"
        }

    # 2. Use anonymized, aggregated profiles only.
    candidates = [
        peer for peer in peer_database
        if peer["anonymized"]
        and peer["user_id"] != current_user_id
        and peer["sharing_consent"]
        and peer["subject"] == user_profile["subject"]
        and peer["age_band"] == user_profile["age_band"]
    ]

    if not candidates:
        return {
            "type": "none",
            "reason": "no_suitable_peer"
        }

    # Do not use sensitive traits, mental-health labels, or raw emotional data.
    candidates = [
        remove_sensitive_attributes(peer)
        for peer in candidates
    ]

    # 3. Determine the educational purpose.
    if strategy == "auto":
        preferred = user_profile.get("comparison_preference")

        if preferred in ["aspiration", "relatability"]:
            strategy = preferred
        elif user_profile.get("recent_mastery_trend") == "stable_or_improving":
            strategy = "aspiration"
        else:
            strategy = "relatability"

    # 4. Aspiration Target:
    # Select a credible next step, not an extreme outlier or "top performer."
    if strategy == "aspiration":
        eligible = [
            peer for peer in candidates
            if peer["mastery_level"] > user_profile["mastery_level"]
            and peer["mastery_level"] <= (
                user_profile["mastery_level"] +
                user_profile.get("aspiration_range", 1)
            )
            and peer["study_habits_shared"]
        ]

        if not eligible:
            return select_peer_for_motivation(
                current_user_id,
                user_emotional_state,
                peer_database,
                user_profile,
                strategy="relatability"
            )

        selected = min(
            eligible,
            key=lambda peer: abs(
                peer["mastery_level"] -
                user_profile["mastery_level"]
            )
        )

        return {
            "type": "aspiration_target",
            "peer_summary": create_aggregated_summary(selected),
            "message": (
                "Here is an example of a learner who was slightly ahead "
                "at this stage. Notice the specific strategy they used."
            ),
            "follow_up": [
                "identify_one_transferable_strategy",
                "set_a_small_next_step",
                "hide_comparison"
            ]
        }

    # 5. Relatability Target:
    # Match by topic, misconception, pace, and strategy—not by distress.
    if strategy == "relatability":
        eligible = [
            peer for peer in candidates
            if overlaps(
                peer["recent_topics"],
                user_profile["recent_topics"]
            )
            and overlaps(
                peer["common_misconceptions"],
                user_profile["current_misconceptions"]
            )
        ]

        if not eligible:
            eligible = [
                peer for peer in candidates
                if peer["mastery_level"] in nearby_mastery_levels(
                    user_profile["mastery_level"]
                )
            ]

        if not eligible:
            return {
                "type": "none",
                "reason": "no_relevant_match"
            }

        selected = max(
            eligible,
            key=lambda peer: similarity_score(
                peer,
                user_profile,
                fields=[
                    "topic",
                    "misconceptions",
                    "learning_pace",
                    "successful_strategies"
                ]
            )
        )

        return {
            "type": "relatability_target",
            "peer_summary": create_aggregated_summary(selected),
            "message": (
                "Another learner encountered a similar challenge and found "
                "this approach useful. You can try it, or choose a different "
                "explanation."
            ),
            "follow_up": [
                "try_peer_strategy",
                "request_alternative_explanation",
                "hide_comparison"
            ]
        }

    raise ValueError("Unknown peer-selection strategy")
