def offer_focus_support(user_id, activity_data, tutor_state, preferences):
    """
    Privacy-preserving alternative to intercept_external_help_seeking.

    Uses only signals generated inside the tutor. It does not inspect:
      - clipboard contents
      - browser history or URLs
      - other applications
      - keystrokes outside the tutor
