    repeated_errors = activity_data.get("consecutive_errors", 0)
    idle_seconds = activity_data.get("idle_seconds", 0)
    rapid_retries = activity_data.get("rapid_retries", 0)
    hint_requests = activity_data.get("hint_requests", 0)

