        tutor_state.get("same_step_duration_seconds", 0) >= 180 or
        tutor_state.get("explicit_help_request", False)
    )

    if not stuck:
        return {"action": "none"}

    # Give the learner control over the next step.
    return {
        "action": "offer_learning_choices",
        "message": (
            "Would you like a hint, a worked example, a prerequisite review, "
            "or time to consult another resource?"
        ),
        "options": [
            "scaffolding_hint",
            "worked_example",
            "review_prerequisite",
            "independent_attempt",
            "use_external_resource",
            "take_break"
        ],
        "explanation": (
            "These options are based on your activity in this lesson; "
            "the tutor does not monitor other apps or clipboard contents."
        )
    }


