    """Reveal the smallest useful next step without giving away the answer."""
    return {
        "action": "scaffolding_hint",
        "hint": generate_minimal_hint(
            problem=tutor_state["current_problem"],
            attempts=tutor_state.get("attempt_history", [])
        ),
        "next_choice": [
