    }


def record_external_resource_use(user_id, resource_metadata, consent):
    """
    Optional learner-controlled reflection.
    Store only what the learner explicitly submits, not passive browsing data.
    """
    if not consent:
        return {"stored": False}

    return {
        "stored": True,
        "purpose": "optional study reflection",
        "data": {
            "resource_type": resource_metadata.get("resource_type"),
            "learner_summary": resource_metadata.get("learner_summary")
        }
    }
